{
  "findings": [
    {
      "check_id": "CKV_AWS_169",
      "title": "SSM Document permissions should not be shared with specific accounts unless necessary",
      "resource": "aws_ssm_document.pass2",
      "severity": "MEDIUM",
      "explanation": "The SSM document is explicitly shared with a specific AWS account ID (680235478471). Unless this cross-account sharing is strictly required for the use case, it expands the attack surface by allowing external principals to execute or view the document. Best practice is to keep documents private within the owning account."
    }
  ],
  "patched_code": "resource "aws_ssm_document" "pass2" {
  name          = "test_document"
  document_type = "Command"

  content = <<DOC
  {
    "schemaVersion": "1.2",
    "description": "Check ip configuration of a Linux instance.",
    "parameters": {

    },
    "runtimeConfig": {
      "aws:runShellScript": {
        "properties": [
          {
            "id": "0.aws:runShellScript",
            "runCommand": ["ifconfig"]
          }
        ]
      }
    }
  }
DOC
}
",
  "fix_summary": "Removed the `permissions` block from the `aws_ssm_document` resource to prevent unnecessary cross-account sharing, ensuring the document remains private to the creating account."
}
